            let best=null,bd=1e9;this.enemies.children.iterate(e=>{if(e&&e.active&&!hit.has(e)){const d=this.dist(e.x,e.y,this.player.x,this.player.y);if(d<760&&d<bd){bd=d;best=e;}}});cur=best;
