  /* ---- ‡∏£‡∏∞‡∏ö‡∏ö‡∏ó‡∏≥‡∏≠‡∏≤‡∏´‡∏≤‡∏£ (Recipe) ‚Äî ‡∏ß‡∏±‡∏ï‡∏ñ‡∏∏‡∏î‡∏¥‡∏ö(Attack Skill a) + ‡πÄ‡∏Ñ‡∏£‡∏∑‡πà‡∏≠‡∏á‡∏õ‡∏£‡∏∏‡∏á(Passive b) = Cook Dish ----
     ‡∏õ‡∏•‡∏∏‡∏Å COMBOS ‡πÄ‡∏î‡∏¥‡∏°‡∏ó‡∏µ‡πà‡πÄ‡∏Ñ‡∏¢‡∏ï‡∏≤‡∏¢‡πÉ‡∏´‡πâ‡∏Å‡∏•‡∏±‡∏ö‡∏°‡∏≤‡∏°‡∏µ‡∏Ñ‡∏ß‡∏≤‡∏°‡∏´‡∏°‡∏≤‡∏¢: ‡∏°‡∏µ‡∏Ñ‡∏π‡πà‡∏Ñ‡∏£‡∏ö = "Cook Dish" times‡πÄ‡∏î‡∏µ‡∏¢‡∏ß ‚Üí ‡∏ö‡∏±‡∏ü‡πÄ‡∏•‡πá‡∏Å + ‡πÇ‡∏°‡πÄ‡∏°‡∏ô‡∏ï‡πå‡∏ó‡∏≥‡∏≠‡∏≤‡∏´‡∏≤‡∏£ */
  checkCombos(){
    this.comboFlags={};
    if(!this.combosOwned)this.combosOwned={};
    for(const c of COMBOS){
      const hasA=(this.skills&&this.skills[c.a]>0);
      const hasB=(this.passives&&this.passives[c.b]>0);
      if(hasA&&hasB){
        this.comboFlags[c.key]=true;
        // ‡πÄ‡∏≠‡∏≤‡∏£‡∏∞‡∏ö‡∏ö codex ‡∏õ‡∏£‡∏∏‡∏á (cookbook/banner/discover) ‡∏≠‡∏≠‡∏Å ‚Äî ‡∏Ñ‡∏á‡πÄ‡∏â‡∏û‡∏≤‡∏∞‡πÇ‡∏ö‡∏ô‡∏±‡∏™ combo ‡πÅ‡∏ö‡∏ö‡πÄ‡∏á‡∏µ‡∏¢‡∏ö ‡πÜ ‡∏Å‡∏±‡∏ô‡∏ö‡∏¥‡∏•‡∏î‡πå‡πÄ‡∏™‡∏µ‡∏¢‡∏ö‡∏≤‡∏•‡∏≤‡∏ô‡∏ã‡πå
        if(!this.combosOwned[c.key]){ this.combosOwned[c.key]=true;
          if(this.player){ if(c.effect)c.effect(this.player); else this.player.dmgMul=Math.min(3.25,(this.player.dmgMul||1)*1.05);
            this.player.dmgMul=Math.min(3.25,this.player.dmgMul);this.player.dmgTakenMul=Math.max(0.35,this.player.dmgTakenMul);this.player.critChance=Math.min(0.40,this.player.critChance);this.player.cdMul=Math.max(0.72,this.player.cdMul);this.player.baseSpeed=Math.min(BALANCE.moveSpeed*1.35,this.player.baseSpeed); } }
      }
    }
  }
  // Cook Dish‡πÉ‡∏´‡∏°‡πà: ‡∏ö‡∏±‡∏ü‡∏î‡∏≤‡πÄ‡∏°‡∏à‡πÄ‡∏•‡πá‡∏Å (prototype) + ‡πÅ‡∏ö‡∏ô‡πÄ‡∏ô‡∏≠‡∏£‡πå "Dish Cooked!" + ‡πÄ‡∏™‡∏µ‡∏¢‡∏á
  cookDish(c){
    if(this.player){
      if(c.effect)c.effect(this.player); else this.player.dmgMul=Math.min(3.25,(this.player.dmgMul||1)*1.05);
      this.player.dmgMul=Math.min(3.25,this.player.dmgMul);this.player.dmgTakenMul=Math.max(0.35,this.player.dmgTakenMul);this.player.critChance=Math.min(0.40,this.player.critChance);this.player.cdMul=Math.max(0.72,this.player.cdMul);this.player.baseSpeed=Math.min(BALANCE.moveSpeed*1.35,this.player.baseSpeed);
    }
    const ai=SKILLDEFS[c.a], bi=PASSIVES[c.b];
    const recipe=((ai&&ai.emoji)||'üç¨')+' + '+((bi&&bi.emoji)||'‚ú®');
    this.dishCount=(this.dishCount||0)+1;
    // ‡∏™‡∏°‡∏∏‡∏î‡∏™‡∏π‡∏ï‡∏£: ‡∏Ñ‡πâ‡∏ô‡∏û‡∏ö‡∏Ñ‡∏£‡∏±‡πâ‡∏á‡πÅ‡∏£‡∏Å = ‡∏£‡∏≤‡∏á‡∏ß‡∏±‡∏• Sugar ‡∏ñ‡∏≤‡∏ß‡∏£ + ‡∏õ‡πâ‡∏≤‡∏¢‡∏û‡∏¥‡πÄ‡∏®‡∏©
    const rew=Save.discoverDish(c.key,c.sig);
    const head=(c.sig?'‚≠ê Signature dish! ':'üç≥ Dish cooked! ')+c.emoji+' '+c.name;
    let sub=recipe+' ‚Üí '+c.desc; if(rew>0)sub='üÜï New recipe! +üç¨'+rew+' ¬∑ '+c.desc;
    this.showBanner(head, sub, c.sig?2100:1700);   // ‡∏£‡∏≤‡∏á‡∏ß‡∏±‡∏•‡∏Ñ‡πâ‡∏ô‡∏û‡∏ö‡πÄ‡∏Ç‡πâ‡∏≤‡∏Ñ‡∏•‡∏±‡∏á Sugar ‡∏ñ‡∏≤‡∏ß‡∏£‡∏ó‡∏±‡∏ô‡∏ó‡∏µ (Save.discoverDish ‡∏ö‡∏±‡∏ô‡∏ó‡∏∂‡∏Å‡πÅ‡∏•‡πâ‡∏ß)
    Sfx.clear(); if(Sfx.pop)Sfx.pop();
  }

  // zoom ‡∏Å‡∏•‡πâ‡∏≠‡∏á‡πÉ‡∏´‡πâ "visible field width" ‡∏Ñ‡∏á‡∏ó‡∏µ‡πà‡∏ó‡∏∏‡∏Å‡πÄ‡∏Ñ‡∏£‡∏∑‡πà‡∏≠‡∏á (‡∏≠‡πâ‡∏≤‡∏á‡∏≠‡∏¥‡∏á‡∏°‡∏∑‡∏≠‡∏ñ‡∏∑‡∏≠ ~430px) ‚Äî ‡πÅ‡∏ó‡πá‡∏ö‡πÄ‡∏•‡πá‡∏ï‡∏à‡∏≠‡∏Å‡∏ß‡πâ‡∏≤‡∏á = zoom ‡πÄ‡∏Ç‡πâ‡∏≤‡∏°‡∏≤‡∏Å‡∏Ç‡∏∂‡πâ‡∏ô ‡∏ï‡∏±‡∏ß‡∏•‡∏∞‡∏Ñ‡∏£‡πÑ‡∏°‡πà‡πÄ‡∏•‡πá‡∏Å‡∏à‡∏¥‡πã‡∏ß
  computeViewZoom(){ const REF_W=430, BASE=0.76; this.viewZoom=BASE*Phaser.Math.Clamp((this.W||REF_W)/REF_W,1,2.4); }
  // ‡∏ã‡∏π‡∏°‡∏≠‡∏≠‡∏Å‡∏£‡∏∞‡∏´‡∏ß‡πà‡∏≤‡∏á‡∏ö‡∏≠‡∏™‡∏î‡πâ‡∏ß‡∏¢ lerp ‡∏ï‡πà‡∏≠‡πÄ‡∏ü‡∏£‡∏° ‡πÄ‡∏û‡∏∑‡πà‡∏≠‡πÉ‡∏´‡πâ‡πÄ‡∏´‡πá‡∏ô‡∏™‡∏ô‡∏≤‡∏°‡∏Å‡∏ß‡πâ‡∏≤‡∏á‡πÅ‡∏•‡∏∞‡∏ó‡∏≥‡∏á‡∏≤‡∏ô‡∏™‡∏°‡πà‡∏≥‡πÄ‡∏™‡∏°‡∏≠‡∏ó‡∏∏‡∏Å‡∏≠‡∏∏‡∏õ‡∏Å‡∏£‡∏ì‡πå
  applyMainZoom(){ if(this.cameras&&this.cameras.main)this.cameras.main.setZoom((this.viewZoom||1)*RENDER_DPR*(this._bossZoom||1)); }
  tickBossZoom(){
    const want=this.mode==='boss'?0.58:(this.mode==='mini'?0.68:1);
    if(this._bossZoom==null)this._bossZoom=1;
    if(Math.abs(this._bossZoom-want)>0.003){this._bossZoom+=(want-this._bossZoom)*0.10;this.applyMainZoom();}
    else if(this._bossZoom!==want){this._bossZoom=want;this.applyMainZoom();}
  }
